   string[] files={"EO1_SOLO.SPH","EO2_SOLO.SPH","EO4_SOLO.SPH"},hashes={"C944009066505B63648411F822CA4D6A1B113BCC911B1B7B9E8DA4CC680EFD1D","AE092979A9610B7AF89DA5F4A43E44DC6A6DB28F4E93524130953C65B9088BAA","805F6720AC80C6AC79EAE44ABB1F9A0037C65C073013DB68A812F298C26409C1"};int[] groups={28,29,38};for(int i=0;i<3;i++){byte[] b=File.ReadAllBytes(Path.Combine(graphics,files[i]));if(Hash(b)!=hashes[i])throw new Exception("Sprite identity");Write(0x210000+i*0x10000,b);W(0x563090+groups[i]*4,P(0x610000+i*0x10000));}
